-- Execute este script no SQL Editor do Supabase APÓS executar supabase_schema.sql
-- Remove constraint restritiva para aceitar 'Comum' e novos membros da família
ALTER TABLE public.transactions DROP CONSTRAINT IF EXISTS transactions_responsavel_check;
ALTER TABLE public.credit_cards DROP CONSTRAINT IF EXISTS credit_cards_titular_check;

ON CONFLICT (id) DO UPDATE SET
    data = EXCLUDED.data,
    ciclo = EXCLUDED.ciclo,
    tipo = EXCLUDED.tipo,
    categoria = EXCLUDED.categoria,
    descricao = EXCLUDED.descricao,
    valor = EXCLUDED.valor,
    responsavel = EXCLUDED.responsavel,
    forma_pagamento = EXCLUDED.forma_pagamento,
    origem_comprovante = EXCLUDED.origem_comprovante,
    cartao_nome = EXCLUDED.cartao_nome;

-- Atualizar o contador do ID da sequência
SELECT setval(pg_get_serial_sequence('public.transactions', 'id'), COALESCE(MAX(id), 1)) FROM public.transactions;
